import sys
input = sys.stdin.read

def solve():
    data = input().split()
    n = int(data[0])
    strings = data[1:]

    countA = {}
    countB = {}

    for s in strings:
        bal = 0
        min_bal = 0
        for ch in s:
            if ch == '(':
                bal += 1
            else:
                bal -= 1
            min_bal = min(min_bal, bal)

        if min_bal >= 0 and bal >= 0:
            countA[bal] = countA.get(bal, 0) + 1
        else:
            # check if can be type B
            bal2 = 0
            min_bal2 = 0
            for ch in reversed(s):
                if ch == ')':
                    bal2 += 1
                else:
                    bal2 -= 1
                min_bal2 = min(min_bal2, bal2)
            if min_bal2 >= 0 and bal2 >= 0:
                # original balance is -bal2
                orig_bal = -bal2
                countB[orig_bal] = countB.get(orig_bal, 0) + 1

    ans = 0
    for b, cnt in countA.items():
        if -b in countB:
            ans += min(cnt, countB[-b])

    print(ans)

if __name__ == "__main__":
    solve()

